async function mapLimit(items, limit, fn) {
  const hasil = [];
  const executing = new Set();
  for (const [i, item] of items.entries()) {
    const p = Promise.resolve().then(() => fn(item)).then(r => {
      hasil[i] = r; executing.delete(p);
    });
